"""Conteúdo editorial. Edite aqui e execute tools/generate.py. HTML simples permitido."""
from html import escape

def p(text): return '<p>'+text+'</p>'
def steps(*items): return '<ol class="steps">'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
def note(text, warning=False): return '<aside class="callout'+(' warning' if warning else '')+'">'+p(text)+'</aside>'
def shot(name, caption):
    return f'<figure class="screenshot"><a href="../assets/screenshots/{name}.jpg" class="zoom-image" aria-label="Ampliar captura: {escape(caption, quote=True)}"><img src="../assets/screenshots/{name}.jpg" alt="{escape(caption, quote=True)}" loading="lazy" width="1440"></a><figcaption>{caption} <span class="zoom-hint">Clique ou pressione Enter para ampliar.</span></figcaption></figure>'
def table(head, rows): return '<div class="table-wrap"><table class="table"><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def link(slug,text): return f'<a href="{slug}.html">{text}</a>'

pages=[]
def page(slug,group,title,description,prereq,path,sections,result,rules):
    pages.append(dict(slug=slug,group=group,title=title,description=description,prereq=prereq,path=path,sections=sections,result=result,rules=rules))

page('index','Começando','Manual do familiar','Encontre o caminho para solicitar cuidado para você ou para alguém da sua família, do primeiro cadastro ao acompanhamento do atendimento.','Nenhum. Para praticar os tutoriais, tenha acesso à myzelo e a uma caixa de e-mail.','Central de ajuda → Familiar',[
 ('visao-geral','O que você pode fazer',p('Na área familiar, você cadastra as pessoas que receberão cuidado, informa onde e quando o atendimento deve acontecer e acompanha sua solicitação. O profissional usa uma área própria; aqui você verá apenas as ações da família.')+shot('historico','Área familiar: solicitações e histórico em um só lugar.')),
 ('roteiro','Seu caminho pela myzelo','<ol class="step-track"><li>1. Criar conta</li><li>2. Preparar cadastros</li><li>3. Solicitar cuidado</li><li>4. Acompanhar</li><li>5. Confirmar conclusão</li></ol>'+steps(link('criar-conta','Crie sua conta familiar')+' e '+link('primeiro-acesso','conclua o primeiro acesso')+'.',link('pessoas-assistidas','Cadastre a pessoa assistida')+' e confira os '+link('dados-fiscais','dados fiscais')+'.',link('solicitar-cuidado','Preencha as cinco etapas da solicitação')+'.',link('pagamento','Confirme a reserva com o pagamento de teste')+'.',link('atendimento','Acompanhe o atendimento e confirme a conclusão')+'.')),
 ('como-usar','Como usar este manual',p('Escolha um assunto no menu lateral ou pesquise por uma tarefa. Em telas pequenas, use o botão de menu no cabeçalho. Cada captura pode ser ampliada: escolha <strong>Tamanho original</strong> para ler detalhes e role a imagem; use <strong>Fechar</strong> ou a tecla <strong>Esc</strong> para voltar. Os links ao final de cada página levam ao assunto anterior e ao próximo.')+p('As telas usam a família fictícia de Marina Oliveira e Helena Oliveira. Nenhum dado representa uma contratação real. Os botões desenhados nas capturas são imagens; as instruções devem ser executadas na aplicação.')),
 ('versao','Sobre esta entrega',note('<strong>Ambiente de demonstração:</strong> os pagamentos e valores mostrados nas capturas de 07/10 são simulados. Não use esse exemplo como tabela de preços nem como descrição das integrações financeiras da versão atual em produção.')+p('A base visual e os tutoriais de demonstração foram revisados em <strong>7 de outubro de 2026</strong>, na revisão <strong>1d2aba5e77bc</strong> com alterações locais. Em <strong>24 de outubro de 2026</strong>, os textos de cadastro e primeiro acesso receberam atualização parcial com base no código <strong>700681250c76</strong>, incluindo o convite por e-mail. A Ajuda também recebeu uma orientação sobre ícones ausentes no navegador ou aplicativo de senhas, com referência na correção <strong>55cf4596b8d7</strong>; a publicação dessa correção e o resultado no aplicativo de senhas não foram confirmados nesta atualização. A apresentação da validade no e-mail do convite foi conferida na revisão <strong>dd9e60d41a96</strong>: ela mostra apenas data e hora. O CI e o deploy desse ajuste foram confirmados em <strong>24 de outubro de 2026</strong>. O recebimento de um novo convite após o deploy ainda precisa de reteste. As capturas antigas foram preservadas; os demais fluxos, especialmente pagamento, não foram revalidados por essa atualização. O manual profissional continua para outra entrega.'))
], 'Você sabe por onde começar e onde encontrar cada tarefa.', ['Use os nomes dos botões como referência; os dados dos exemplos são fictícios.','Os estados e valores exibidos podem mudar conforme a solicitação e a versão do sistema.'])

page('criar-conta','Começando','Criar uma conta familiar','Cadastre o contato responsável por pedir e acompanhar os cuidados.','Um e-mail ao qual você tenha acesso. Você deve estar fora de outra conta.','Página inicial → Solicitar cuidado → Sou Familiar',[
 ('cadastro','Preencher o cadastro',steps('Na página inicial, escolha <strong>Solicitar cuidado</strong>. Na tela de entrada, essa opção aparece com o complemento “Para mim ou minha família”.','Confirme o tipo <strong>Sou Familiar</strong>. Essa escolha leva à jornada de quem procura cuidado.','Preencha <strong>Nome completo</strong> com o nome do responsável pela conta e <strong>E-mail</strong> com um endereço que você consiga acessar.','Crie sua <strong>Senha</strong> e repita o mesmo conteúdo em <strong>Confirmar senha</strong>. Guarde a senha em local seguro.','Clique em <strong>Criar conta</strong>. Se algum campo for recusado, corrija o campo indicado e envie novamente.')+shot('cadastro','Cadastro com a opção Sou Familiar selecionada. As senhas não são exibidas neste manual.')),
 ('convite','Quando você recebeu um convite da equipe',note('<strong>Atualização de 24/10/2026:</strong> o convite de cadastro assistido por e-mail tem um caminho próprio. Você define sua senha; a equipe não cria nem recebe essa senha.')+steps('Saia de outra conta, se estiver conectada. Abra o convite mais recente na caixa do e-mail que você informou à equipe.','Confira a validade no e-mail: ela mostra a data e a hora, por exemplo, <strong>25/10/2026 13:10</strong>. Use o convite dentro do prazo informado.','Clique em <strong>Concluir meu cadastro</strong> no e-mail. Na tela aberta, confira o nome e o e-mail exibidos, preencha a senha e a confirmação e clique em <strong>Concluir cadastro</strong>.','Complete o primeiro acesso com nome e WhatsApp, se solicitado.','O endereço do convite já fica confirmado ao concluir: não é necessário outro e-mail de verificação para esse mesmo endereço. As demais etapas da solicitação de cuidado continuam necessárias.')+p('Se a equipe reenviar o convite, o anterior deixa de funcionar. Depois de usado ou vencido, ele também fica indisponível. Para uma conta já criada, use '+link('entrar','Entrar')+' ou '+link('recuperar-acesso','Recuperar acesso')+'; não tente criar outra com o mesmo endereço.')+note('A mudança não confirma contas antigas retroativamente. Se você concluiu um convite antes da correção e ainda vê a pendência, faça a verificação normal da sua conta. Não compartilhe o link do convite.',True)),
 ('depois','Depois do cadastro comum',p('No cadastro feito por <strong>Criar conta</strong>, a aplicação abre <strong>Vamos configurar sua conta</strong>, a etapa de primeiro acesso, e envia a mensagem de confirmação ao seu e-mail. Esse caminho continua exigindo verificação. Siga '+link('primeiro-acesso','Confirmar e-mail e primeiro acesso')+' para completar a preparação.')+note('O nome da conta identifica o contato principal. Cadastre a pessoa que receberá o cuidado separadamente, mesmo quando você estiver criando a conta para sua mãe, seu pai ou outro familiar.'))
], 'Sua conta familiar é criada e você chega à configuração inicial.', ['O e-mail precisa ter formato válido e não pode já estar em uso por outra conta.','Senha e confirmação devem ser iguais; siga a validação apresentada pelo sistema.','A opção Continuar com Google está marcada como “Em breve” na tela de entrada. Use e-mail e senha.'])

page('primeiro-acesso','Começando','Confirmar e-mail e primeiro acesso','Configure o contato da família e libere o envio de solicitações.','Conta familiar criada e acesso à caixa do e-mail cadastrado.','Após Criar conta → Vamos configurar sua conta; alerta no topo → Reenviar verificação',[
 ('configurar','Concluir a configuração',steps('Confira <strong>Nome completo</strong> do responsável.','Preencha <strong>WhatsApp</strong>, incluindo DDD.','Clique em <strong>Concluir configuração</strong>.','Você será levado a <strong>Solicitações de cuidado</strong>, onde poderá começar seu primeiro pedido.')+shot('primeiro-acesso','Captura de 07/10: nome, WhatsApp e orientação do cadastro comum sobre confirmação de e-mail.')),
 ('convite-confirmado','Se você concluiu um convite por e-mail',note('<strong>Atualização parcial de 24/10/2026:</strong> ao concluir um convite válido enviado pela equipe por e-mail, o endereço desse convite já é confirmado. Não repita a verificação descrita abaixo para o mesmo endereço. Isso não dispensa a configuração familiar nem confirma contas antigas retroativamente.')+p('As instruções da próxima seção continuam valendo para o cadastro comum e para um novo endereço informado depois em '+link('perfil','Meu perfil')+'. Confira o caminho de <a href="criar-conta.html#convite">cadastro pelo convite</a> antes de reenviar verificações desnecessárias.')),
 ('confirmar','Verificar o e-mail',steps('Abra a mensagem da myzelo com o assunto <strong>Confirme seu endereço de e-mail</strong>.','Clique em <strong>Verificar e-mail</strong> na mensagem. Se for necessário, entre na mesma conta familiar.','Volte à aplicação. A mensagem que exige confirmação deixa de aparecer e o envio da solicitação passa a ser permitido quando as etapas estiverem completas.','Se a mensagem não chegou, confira spam e o endereço informado. Use <strong>Reenviar verificação</strong> no aviso do topo. Em <strong>Meu perfil</strong>, a ação equivalente é <strong>Reenviar e-mail</strong>.')+shot('revisao-email-pendente','Sem confirmar o e-mail, o rascunho fica salvo, mas Enviar solicitação permanece desabilitado.')),
 ('pendencias','Entender as pendências',p('A confirmação de e-mail e os dados fiscais têm momentos diferentes. Você pode salvar rascunhos sem confirmar o e-mail. Para enviar, precisa confirmar. Os dados fiscais são necessários quando for autorizar o pagamento de teste.')+note('Não compartilhe o link de confirmação. Se ele estiver expirado ou inválido, solicite outro pelo próprio sistema.'))
], 'Seu contato está configurado e o e-mail confirmado permite enviar solicitações.', ['Sem confirmação de e-mail, a área familiar e os rascunhos continuam acessíveis.','No convite por e-mail válido, a confirmação ocorre ao concluir o cadastro; no cadastro comum, use a mensagem de verificação.','A confirmação não preenche seus dados fiscais automaticamente.','Ao alterar o e-mail do perfil, será necessário confirmar o novo endereço.'])

page('entrar','Começando','Entrar e sair da conta','Acesse sua área familiar e encerre a sessão quando terminar.','Conta familiar já cadastrada.','Página inicial → Entrar',[
 ('acessar','Entrar com e-mail e senha',steps('Abra <strong>Entrar</strong>.','Preencha <strong>E-mail</strong> e <strong>Senha</strong> da sua conta familiar.','Clique em <strong>Entrar</strong>. Se ainda faltar a configuração inicial, conclua o nome e o WhatsApp.','Ao entrar, confira o nome no menu da conta para ter certeza de que está usando o acesso correto.')+shot('login','Acesso com e-mail e senha, com as entradas separadas para solicitar cuidado ou atuar como profissional.')),
 ('sair','Encerrar sua sessão',steps('Abra o menu da conta, identificado pelo seu nome.','Escolha <strong>Sair</strong>.','Para retornar, entre novamente com suas credenciais.')+p('Se não lembrar sua senha, siga '+link('recuperar-acesso','Recuperar acesso — esqueci a senha')+'.'))
], 'Você acessa a área familiar ou encerra a sessão com segurança.', ['O tipo da conta determina a área aberta após o login. Não há uma troca de familiar para profissional dentro deste manual.','Não é necessário fazer um novo cadastro para cada pessoa assistida.','Se houver erro de acesso, confira o e-mail e use a recuperação de senha.'])

page('navegacao','Conhecendo o sistema','Menus e navegação','Localize as principais ações da área familiar.','Conta familiar com primeiro acesso concluído.','Menu principal da área familiar',[
 ('menus','Onde fica cada função',table(['Menu ou aba','Para que serve'],[['<strong>Solicitações de cuidado</strong>','Criar solicitações, continuar rascunhos e visualizar o histórico.'],['<strong>Pessoas assistidas</strong>','Adicionar pessoas e editar seus dados cadastrais.'],['<strong>Meu perfil → Dados do perfil</strong>','Atualizar nome, e-mail e WhatsApp.'],['<strong>Meu perfil → Dados fiscais</strong>','Informar o contratante e o endereço fiscal.'],['<strong>Meu perfil → Senha e segurança</strong>','Alterar a senha da conta.'],['<strong>Menu com seu nome → Sair</strong>','Encerrar a sessão.']])+shot('historico','O menu principal permanece disponível enquanto você navega pela área familiar.')),
 ('usar','Encontrar a próxima ação',steps('Entre em <strong>Solicitações de cuidado</strong>.','Use <strong>Nova solicitação</strong> para começar. Em um rascunho, use <strong>Continuar</strong>. Em uma solicitação enviada, use <strong>Visualizar</strong>.','Dentro dos detalhes, use <strong>Voltar às solicitações</strong> para retornar à lista.','Durante o preenchimento, clique no nome de uma etapa já disponível para revisá-la. Salve alterações com <strong>Próximo</strong>.')+note('Em telas pequenas, abra o menu de navegação para acessar as mesmas áreas. As abas de Meu perfil podem exigir rolagem horizontal.'))
], 'Você consegue localizar cadastros, solicitações e configurações.', ['A ação disponível depende do estado: Continuar para rascunho, Visualizar depois do envio.','As telas de perfil profissional não fazem parte da navegação familiar.'])

page('pessoas-assistidas','Cadastros','Cadastrar e editar pessoas assistidas','Mantenha os dados de quem poderá receber cuidado e reutilize-os nas solicitações.','Conta familiar configurada.','Menu principal → Pessoas assistidas',[
 ('adicionar','Adicionar uma pessoa',steps('Abra <strong>Pessoas assistidas</strong> e clique em <strong>Adicionar pessoa</strong>.','Informe <strong>Nome</strong> e <strong>Relação familiar</strong>, por exemplo, “Helena Oliveira” e “Mãe”.','Preencha <strong>Data de nascimento</strong> e <strong>Gênero</strong> se desejar informar esses dados.','Clique em <strong>Adicionar</strong> e confira o cartão da pessoa na lista.')+shot('adicionar-pessoa','Adicionar pessoa: nome e relação familiar identificam o cadastro.')),
 ('editar','Corrigir um cadastro',steps('No cartão da pessoa, clique em <strong>Editar</strong>.','Confira os campos da janela <strong>Editar pessoa</strong>.','Altere as informações necessárias e clique em <strong>Salvar alterações</strong>.','Confira os dados atualizados no cartão.')+shot('editar-pessoa','Edição de Helena Oliveira no cadastro de pessoas assistidas.')),
 ('reutilizar','Usar em uma solicitação',p('Na etapa <strong>Pessoa assistida</strong> de uma nova solicitação, escolha <strong>Pessoa cadastrada</strong> e selecione o cadastro. Você também pode cadastrar uma pessoa diretamente nessa etapa.')+shot('pessoas-assistidas','Pessoas assistidas mostra os dados já cadastrados e a ação Editar.')+note('Se a opção escolhida for <strong>Eu</strong>, o nome acompanha os dados da conta. Para corrigir o nome do titular, use <strong>Meu perfil → Dados do perfil</strong>.'))
], 'A pessoa fica cadastrada e pode ser selecionada em novas solicitações.', ['Nome e relação familiar são obrigatórios para uma nova pessoa.','A data de nascimento não pode ser futura.','Solicitações já enviadas preservam os dados registrados no envio; editar o cadastro não reescreve esse histórico.','A tela atual de Pessoas assistidas apresenta Adicionar e Editar; não oferece exclusão no cartão.'])

page('enderecos','Cadastros','Cadastrar o endereço de atendimento','Informe o local onde o cuidado acontecerá e reutilize um endereço salvo.','Uma solicitação em rascunho com a pessoa assistida definida.','Solicitações de cuidado → Nova solicitação ou Continuar → Endereço',[
 ('novo','Informar um novo endereço',steps('Na etapa <strong>Onde será o atendimento?</strong>, selecione <strong>Novo endereço</strong>.','Preencha o <strong>CEP</strong> e aguarde a consulta. Confira o preenchimento de <strong>Logradouro</strong>, <strong>Bairro</strong>, <strong>Cidade</strong> e <strong>UF</strong>.','Informe <strong>Número</strong> e, se necessário, <strong>Complemento</strong>.','Escolha <strong>Local do atendimento</strong>: Residência, Hospital, Clínica ou Outro local.','Clique em <strong>Próximo</strong> para salvar e continuar.')+shot('solicitacao-2-endereco','Endereço do atendimento e tipo de local na segunda etapa da solicitação.')),
 ('salvo','Reutilizar um endereço',steps('Em outra solicitação, abra a etapa <strong>Endereço</strong>.','Escolha <strong>Endereço cadastrado</strong>. A opção fica disponível quando houver endereço salvo.','Selecione o endereço e confira o local do atendimento.','Clique em <strong>Próximo</strong>.')+note('A consulta por CEP é uma ajuda de preenchimento. Revise os campos antes de avançar; se a consulta não funcionar, preencha os dados manualmente.')),
 ('fiscal','Diferenciar os dois endereços',p('O endereço desta etapa é onde o cuidado será prestado. O endereço de <strong>Dados fiscais</strong> identifica o titular do contrato e da nota fiscal. Salvar um deles não substitui o outro.')+p('O caminho disponível na navegação familiar para cadastrar e selecionar o local é a etapa Endereço. Não procure uma aba “Endereços” no menu principal atual.'))
], 'O endereço é salvo e vinculado ao rascunho.', ['CEP, logradouro, número, bairro, cidade e UF devem estar preenchidos corretamente; complemento é opcional.','O endereço precisa pertencer aos cadastros da própria família.','O endereço registrado no envio permanece no histórico da solicitação.'])

page('dados-fiscais','Cadastros','Preencher dados fiscais','Prepare os dados do contratante para não interromper a autorização do pagamento de teste.','Primeiro acesso familiar concluído.','Meu perfil → Dados fiscais',[
 ('preencher','Cadastrar o contratante',steps('Abra <strong>Meu perfil</strong> e escolha a aba <strong>Dados fiscais</strong>. Você também pode usar <strong>Preencher dados fiscais</strong> em um aviso de pendência.','Em <strong>Identificação fiscal</strong>, informe <strong>Nome do contratante</strong>, <strong>CPF</strong> e <strong>E-mail da nota fiscal</strong>.','Em <strong>Endereço fiscal</strong>, preencha CEP, Logradouro, Número, Complemento quando houver, Bairro, Cidade e UF. Confira qualquer dado preenchido pela consulta do CEP.','Clique em <strong>Salvar dados fiscais</strong>. O sistema informa “Dados fiscais atualizados.”','Volte a <strong>Solicitações de cuidado</strong>, abra a solicitação reservada e retome <strong>Simular pagamento</strong>.')+shot('dados-fiscais','Dados fiscais preenchidos com informações fictícias de treinamento.')),
 ('pendente','Quando faltam dados fiscais',p('Na reserva, a tela de pagamento mostra <strong>Complete os dados do contratante</strong> e oferece <strong>Preencher dados fiscais</strong>. A autorização não fica disponível enquanto os dados necessários não estiverem completos.')+shot('pagamento-pendente','Pendência fiscal impede autorizar o pagamento de teste.')+note('O prazo da reserva continua passando enquanto você preenche os dados. Se ele terminar, a solicitação volta à busca por profissionais.',True))
], 'Os dados fiscais ficam salvos e a pendência deixa de bloquear o pagamento de teste.', ['O CPF é validado; sequências inválidas não são aceitas.','O e-mail da nota fiscal pode ser diferente do e-mail usado para entrar.','O endereço fiscal não altera o endereço do atendimento.','Nesta versão, o cadastro fiscal não significa emissão automática de nota fiscal.'])

page('solicitar-cuidado','Solicitar cuidado','Solicitar cuidado em cinco etapas','Descreva quem precisa de cuidado, o local, a agenda e as necessidades antes de enviar.','Conta familiar configurada. Confirme o e-mail antes do envio.','Solicitações de cuidado → Nova solicitação',[
 ('pessoa','1. Pessoa assistida',steps('Clique em <strong>Nova solicitação</strong>. Abrir a tela ainda não cria um rascunho.','Em <strong>Quem receberá o cuidado?</strong>, escolha <strong>Nova pessoa</strong>, <strong>Pessoa cadastrada</strong> ou <strong>Eu</strong>.','Para Nova pessoa, preencha <strong>Nome completo</strong> e <strong>Relação familiar</strong>. Data de nascimento e gênero são opcionais. Para Pessoa cadastrada, selecione o cadastro desejado.','Clique em <strong>Próximo</strong>. A partir daqui, o rascunho existe e poderá ser retomado.')+shot('solicitacao-1-pessoa','Etapa 1: cadastro de Helena Oliveira como pessoa assistida.')),
 ('endereco','2. Endereço',steps('Escolha um endereço cadastrado ou <strong>Novo endereço</strong>.','Confira CEP, Logradouro, Número, Complemento, Bairro, Cidade e UF.','Selecione <strong>Local do atendimento</strong> e clique em <strong>Próximo</strong>.')+shot('solicitacao-2-endereco','Etapa 2: local onde o cuidado será prestado.')),
 ('agenda','3. Agenda',steps('Marque pelo menos um dos <strong>Dias da semana</strong>.','Selecione <strong>Duração por dia</strong>: 4, 6, 8, 12 ou 24 horas.','Informe <strong>Data de início</strong> e <strong>Horário</strong>. A data não pode ser anterior ao dia atual.','Clique em <strong>Próximo</strong>. Se a página indicar um erro, corrija-o antes de continuar.')+shot('solicitacao-3-agenda','Etapa 3: quarta-feira, quatro horas por dia, início em 07/10/2026 às 09:00. Esta data pertence ao exemplo capturado.')),
 ('necessidades','4. Necessidades',steps('Selecione <strong>Autonomia</strong>: Independente, Assistência parcial ou Dependência total.','Escolha a <strong>Mobilidade</strong> que representa a situação da pessoa.','Marque pelo menos uma das <strong>Atividades desejadas</strong>.','Em <strong>Procedimentos de enfermagem</strong>, escolha os procedimentos necessários ou <strong>Nenhum procedimento</strong>. Se selecionar Outro procedimento, descreva-o no campo apresentado.','Use <strong>Observações adicionais</strong> para complementar a rotina. Clique em <strong>Próximo</strong>.')+shot('solicitacao-4-necessidades','Etapa 4: autonomia, mobilidade, atividades e procedimentos.')+note('“Nenhum procedimento” deve ficar sozinho. Para indicar um procedimento, desmarque essa opção. As necessidades devem refletir o cuidado solicitado.')),
 ('revisao','5. Revisão e envio',steps('Em <strong>Revise sua solicitação</strong>, confira pessoa, endereço, agenda, início, condições de cuidado, atividades, procedimentos e observações.','Confira <strong>Valor total da solicitação</strong>. Na versão documentada, ele é um valor temporário de teste.','Para corrigir informações, clique no nome de uma etapa anterior, altere os campos e salve com <strong>Próximo</strong>. Depois retorne à revisão.','Se o e-mail estiver pendente, confirme-o antes de continuar.','Clique em <strong>Enviar solicitação</strong>. A tela de detalhes passa a mostrar <strong>Buscando profissional</strong>.')+shot('solicitacao-5-revisao','Etapa 5: resumo completo, valor temporário e botão Enviar solicitação.')+note('Revise antes de enviar. A solicitação enviada deixa de ser rascunho e não apresenta edição ou exclusão no fluxo atual.',True))
], 'A solicitação é enviada e pode ser acompanhada nos detalhes e no histórico.', ['Próximo salva a etapa; digitar em um campo sem avançar não garante que a mudança foi salva.','Etapas futuras só são liberadas conforme o preenchimento avança.','O envio exige e-mail confirmado e todas as etapas completas.','O orçamento aceito fica congelado no envio; o valor das capturas não é um preço comercial definitivo.'])

page('rascunhos','Operações','Salvar, retomar e excluir rascunhos','Continue um pedido mais tarde ou descarte um rascunho que não será usado.','Uma solicitação com pelo menos a primeira etapa salva.','Solicitações de cuidado → cartão com estado Rascunho',[
 ('salvar','Salvar e sair',steps('Preencha uma etapa válida e clique em <strong>Próximo</strong>.','Para interromper o preenchimento, abra <strong>Solicitações de cuidado</strong> no menu.','Confira se o cartão aparece como <strong>Rascunho</strong>.')+shot('rascunho','O cartão de rascunho oferece Continuar e Excluir.')),
 ('retomar','Retomar e editar',steps('Localize o cartão da pessoa assistida e clique em <strong>Continuar</strong>.','O sistema abre a etapa em que o rascunho está. No exemplo, a revisão foi retomada com os dados preservados.','Para corrigir uma etapa disponível, selecione seu nome no indicador de progresso.','Faça a alteração e clique em <strong>Próximo</strong>. Revise o conjunto antes de enviar.')+p('Se você apenas abriu Nova solicitação e saiu antes de avançar a primeira etapa, nenhum rascunho foi criado.')),
 ('excluir','Excluir com confirmação',steps('No cartão em Rascunho, clique em <strong>Excluir</strong>.','Leia a janela <strong>Excluir este rascunho?</strong>.','Use <strong>Cancelar</strong> para manter a solicitação ou <strong>Excluir rascunho</strong> para apagá-la.','Após a exclusão, o cartão deixa de aparecer na lista.')+shot('excluir-rascunho','A confirmação explica que a exclusão do rascunho não pode ser desfeita.')+note('Excluir rascunho apaga as informações daquela solicitação. Não use essa ação se pretende continuar o pedido depois.',True))
], 'O rascunho é preservado para continuar ou removido após confirmação.', ['Somente rascunhos podem ser excluídos por essa ação.','Após Enviar solicitação, o cartão oferece Visualizar e segue o acompanhamento.','A exclusão não tem desfazer.'])

page('pagamento','Pagamento e atendimento','Reserva e pagamento simulado','Entenda a reserva e autorize o pagamento de teste dentro do prazo.','Solicitação enviada, profissional reservado e dados fiscais completos.','Solicitações de cuidado → Visualizar → Simular pagamento',[
 ('reserva','Quando um profissional aceita',p('Após o envio, a solicitação fica em <strong>Buscando profissional</strong>. Quando um profissional aceita, passa para <strong>Aguardando pagamento</strong>. A tela identifica quem reservou o atendimento e mostra uma contagem regressiva.')+shot('reserva','Reserva aceita pelo Profissional Teste, com prazo e acesso à simulação.')+note('Nesta configuração, a reserva começa com <strong>30 minutos</strong>. Use o tempo restante exibido na tela como referência. Se o prazo terminar, a reserva expira e a solicitação volta para outros profissionais.',True)),
 ('autorizar','Autorizar o pagamento de teste',steps('Abra os detalhes da solicitação em <strong>Aguardando pagamento</strong>.','Clique em <strong>Simular pagamento</strong>.','Confira o profissional, a solicitação e o valor total. A tela informa <strong>Nenhuma cobrança real será realizada</strong>.','Se aparecer a pendência fiscal, use <strong>Preencher dados fiscais</strong>, salve o cadastro e volte à solicitação.','Enquanto a reserva estiver válida, clique em <strong>Autorizar pagamento de teste</strong>.','Confira a mudança para <strong>Atendimento autorizado</strong>.')+shot('pagamento-simulado','Pagamento de teste liberado: nenhum cartão é solicitado e não há cobrança real.')),
 ('limites','O que esta simulação significa',p('O botão registra a autorização de teste e permite o avanço do atendimento. O valor vem do orçamento aceito no envio. Você não está pagando por cartão ou realizando uma cobrança no Stripe nesta versão.')+shot('atendimento-autorizado','Após autorizar, o atendimento fica confirmado com o profissional reservado.'))
], 'A solicitação passa para Atendimento autorizado e aguarda o início informado pelo profissional.', ['Dados fiscais incompletos impedem a autorização.','O prazo expirado ou uma solicitação fora de Aguardando pagamento impede nova autorização por essa tela.','O valor de R$ 1.000,00 usado no exemplo é temporário; não representa tabela comercial.','O fluxo atual não efetua cobrança real, repasse ou emissão de nota fiscal.'])

page('atendimento','Pagamento e atendimento','Acompanhar e confirmar a conclusão','Veja o andamento do cuidado e registre a confirmação da família ao final.','Solicitação com pagamento de teste autorizado.','Solicitações de cuidado → Visualizar',[
 ('andamento','Acompanhar o início',steps('Abra <strong>Visualizar</strong> na solicitação.','Enquanto aparecer <strong>Atendimento autorizado</strong>, aguarde o profissional informar o início na data combinada.','Quando o profissional iniciar, o estado muda para <strong>Em atendimento</strong>.','Consulte a seção <strong>Andamento</strong> para acompanhar os marcos registrados.')+shot('em-atendimento','Em atendimento: o profissional já informou o início do cuidado.')),
 ('confirmar','Confirmar que o atendimento terminou',steps('Após o profissional informar a conclusão, abra a solicitação em <strong>Aguardando confirmação</strong>.','Leia <strong>Confirme a conclusão do atendimento</strong> e confira se o serviço foi concluído como esperado.','Clique em <strong>Confirmar conclusão</strong> quando estiver de acordo.','Confira o estado <strong>Concluído</strong> e o marco <strong>Conclusão confirmada</strong> em Andamento.')+shot('confirmar-conclusao','A família confirma a conclusão após o aviso do profissional.')+shot('concluido','Solicitação concluída, com a linha do tempo preenchida.')),
 ('divergencia','Se você não concorda com a conclusão',p('Não confirme algo que ainda precisa ser esclarecido. A interface atual exibe <strong>Contestar atendimento — em breve</strong>, desabilitado. Não há fluxo de contestação disponível nessa tela. Esclareça a situação com a equipe responsável pelo ambiente antes de confirmar.')+note('Mesmo depois de Concluído, o pagamento de teste permanece autorizado. Liberação, repasse, disputa e emissão de notas fiscais ainda não são executados nessa versão.'))
], 'A solicitação aparece como Concluído e pode ser consultada no histórico.', ['A família confirma a conclusão somente depois de o profissional informá-la.','Quem informa o início e o término do cuidado é o profissional; esses botões não pertencem à área familiar.','A confirmação de conclusão é uma ação diferente da autorização do pagamento.'])

page('historico','Histórico','Consultar solicitações e estados','Encontre solicitações anteriores e consulte os detalhes registrados no envio.','Pelo menos uma solicitação salva ou enviada.','Menu principal → Solicitações de cuidado',[
 ('consultar','Abrir uma solicitação',steps('Abra <strong>Solicitações de cuidado</strong>.','Localize o cartão pelo nome da pessoa assistida, local, dias e duração.','Confira o estado e clique em <strong>Visualizar</strong> nas solicitações enviadas.','Consulte os dados, o valor e a seção <strong>Andamento</strong>. Use <strong>Voltar às solicitações</strong> para retornar.')+shot('historico','Solicitação concluída disponível na mesma lista usada para acompanhar pedidos ativos.')),
 ('estados','Entender os estados',table(['Estado no cartão','Significado e próxima ação'],[['Rascunho','Ainda não enviado. Use Continuar para terminar ou Excluir para descartar.'],['Buscando profissional','Solicitação enviada e aguardando aceite de um profissional compatível.'],['Aguardando pagamento','Profissional reservado. Abra Visualizar e Simular pagamento antes de acabar o prazo.'],['Atendimento autorizado','Pagamento de teste autorizado. Aguarde o início.'],['Em atendimento','O profissional informou o início. Acompanhe os detalhes.'],['Aguardando confirmação','O profissional informou a conclusão. A família deve conferir e confirmar.'],['Concluído','A família confirmou a conclusão. O registro permanece para consulta.']])),
 ('detalhes','Dados preservados',p('A solicitação enviada guarda a pessoa assistida, o endereço e as condições registradas no momento do envio. Alterações futuras em cadastros não devem ser confundidas com uma edição de pedidos já enviados.')+shot('concluido','Detalhes e marcos de andamento de uma solicitação concluída.')+note('O histórico atual é essa consulta de solicitações. Não há uma área de relatórios, exportação de planilha ou download de relatório demonstrada nesta versão.'))
], 'Você localiza um pedido e entende seu estado e os marcos do atendimento.', ['Rascunhos abrem em Continuar; pedidos enviados abrem em Visualizar.','O envio encerra a edição do rascunho.','Os estados dependem das ações da família e do profissional; atualizar a página não inicia um atendimento.'])

page('perfil','Configurações','Atualizar nome, contato e e-mail','Mantenha os dados de contato do responsável pela conta familiar.','Sessão iniciada na conta familiar.','Meu perfil → Dados do perfil',[
 ('dados','Salvar dados pessoais',steps('Abra <strong>Meu perfil</strong> e a aba <strong>Dados do perfil</strong>.','Na seção <strong>Dados pessoais</strong>, confira <strong>Nome completo</strong>, <strong>E-mail</strong> e <strong>WhatsApp</strong>.','Altere o que for necessário e clique em <strong>Salvar dados pessoais</strong>.','Confira a mensagem de sucesso e os valores exibidos.')+shot('perfil','Nome, e-mail e WhatsApp do responsável familiar.')),
 ('email','Quando você altera o e-mail',steps('Informe o novo endereço em <strong>E-mail</strong> e salve os dados pessoais.','Abra a mensagem enviada ao novo endereço e clique em <strong>Verificar e-mail</strong>.','Até confirmar, use o alerta do topo ou <strong>Reenviar e-mail</strong> no perfil se precisar de outra mensagem.')+note('Alterar o e-mail remove a confirmação anterior. Você continua podendo salvar rascunhos, mas precisa confirmar o novo endereço para enviar novas solicitações.',True)),
 ('separacao','Qual cadastro você está alterando?',p('Este formulário atualiza o responsável pela conta. Para alterar os dados de Helena, por exemplo, abra '+link('pessoas-assistidas','Pessoas assistidas')+'. Para mudar o contratante ou endereço fiscal, use '+link('dados-fiscais','Dados fiscais')+'.'))
], 'Os dados da conta ficam atualizados; se o e-mail mudou, o novo endereço fica pendente de confirmação.', ['Não é permitido usar um e-mail já cadastrado em outra conta.','O nome da pessoa marcada como titular acompanha o nome da conta.','Mudar o contato não muda os dados históricos de solicitações já enviadas.'])

page('senha','Configurações','Alterar a senha','Troque a senha quando ainda tem acesso à sua conta.','Sessão iniciada e conhecimento da senha atual.','Meu perfil → Senha e segurança',[
 ('trocar','Preencher a alteração de senha',steps('Abra <strong>Meu perfil → Senha e segurança</strong>.','Em <strong>Alterar senha</strong>, preencha <strong>Senha atual</strong>.','Digite sua <strong>Nova senha</strong> e repita em <strong>Confirmar nova senha</strong>.','Clique em <strong>Salvar nova senha</strong>. Corrija qualquer erro indicado nos campos.','Nos próximos acessos, use a nova senha. Não a compartilhe em capturas ou mensagens de treinamento.')+shot('seguranca','Tela de alteração de senha, capturada sem preencher credenciais.')),
 ('sem-senha','Se você não lembra a senha atual',p('Use '+link('recuperar-acesso','Recuperar acesso')+' pela tela de entrada. Esse caminho envia uma mensagem para o e-mail cadastrado, em vez de exigir a senha atual.'))
], 'Após uma alteração válida, a nova senha passa a ser utilizada para entrar.', ['A senha atual precisa corresponder à conta.','Nova senha e confirmação devem ser iguais e atender às regras exibidas.','Os botões de mostrar senha revelam o conteúdo na tela; mantenha-os ocultos em apresentações.'])

page('recuperar-acesso','Configurações','Recuperar acesso — esqueci a senha','Solicite um link por e-mail quando não conseguir lembrar sua senha.','Acesso à caixa de e-mail usada no cadastro.','Entrar → Esqueceu a senha?',[
 ('solicitar','Solicitar a mensagem de recuperação',steps('Na tela <strong>Entrar</strong>, clique em <strong>Esqueceu a senha?</strong>.','A página atual se chama <strong>Forgot password</strong>. Preencha <strong>Email address</strong> com o e-mail da conta.','Clique em <strong>Email password reset link</strong> (“Enviar link de recuperação de senha”).','Confira a mensagem de envio e abra a caixa de entrada do e-mail informado.')+shot('recuperar-acesso','A recuperação de acesso ainda usa rótulos em inglês na versão documentada.')+shot('recuperacao-enviada','Confirmação do envio local da mensagem de recuperação.')),
 ('redefinir','Usar o link recebido',steps('Abra a mensagem de redefinição de senha da myzelo. Verifique também a pasta de spam.','Use o botão de redefinição na mensagem. Ele abre a tela <strong>Reset password</strong>.','Confira <strong>Email</strong>, preencha <strong>Password</strong> e repita em <strong>Confirm password</strong>.','Clique em <strong>Reset password</strong>. Após concluir, entre com a senha redefinida.')+shot('redefinir-senha','Tela real de redefinição com campos de senha vazios; o link individual não é publicado.')+note('O link de recuperação é individual. Não compartilhe a mensagem nem publique seu endereço. Se o link estiver inválido ou expirado, solicite uma nova mensagem.'))
], 'Você recebe uma mensagem de recuperação e pode definir uma nova senha.', ['Use o e-mail da conta; o e-mail fiscal não substitui automaticamente o e-mail de acesso.','O formulário e parte das mensagens ainda estão em inglês.','Se não houver acesso à caixa de e-mail, este fluxo sozinho não recupera a conta. Procure a equipe responsável pelo ambiente.'])

page('ajuda','Ajuda','Problemas comuns, perguntas e glossário','Resolva as dúvidas mais frequentes sem perder o ponto em que você parou.','Identifique a tela ou o estado em que está.','Menu deste manual → Ajuda; na aplicação, consulte o aviso próximo ao campo',[
 ('problemas','Problemas comuns',table(['O que aconteceu','Como continuar'],[['Enviar solicitação está desabilitado','Confirme o e-mail e confira se todas as etapas foram salvas. Use Reenviar verificação se necessário.'],['“O campo dias da semana é obrigatório.”','Marque pelo menos um dia na etapa Agenda e clique em Próximo novamente.'],['Data de início não é aceita','Escolha hoje ou uma data futura; confira dia, mês e ano.'],['CPF inválido','Confira todos os dígitos do CPF do contratante e salve os dados fiscais novamente.'],['Não consigo autorizar pagamento','Confira dados fiscais completos, prazo ainda válido e estado Aguardando pagamento.'],['A reserva desapareceu','Se o prazo venceu, a solicitação retorna à busca por profissionais. Consulte os detalhes atualizados.'],['Não encontro meu rascunho','Ele só é criado ao avançar da primeira etapa. Confira também se entrou na conta certa.'],['Não recebi o e-mail','Confira o endereço no perfil e o spam. Reenvie a verificação ou solicite outro link de recuperação.'],['CEP não preenche o endereço','Preencha os campos manualmente e confira cidade e UF antes de salvar.'],['O estado parece desatualizado','Abra os detalhes novamente ou atualize a página. Confira se a ação anterior foi concluída.']])+shot('agenda-validacao','Exemplo real de validação: é preciso informar pelo menos um dia da semana.')),
 ('faq','Perguntas frequentes', ''.join('<details><summary>'+q+'</summary>'+p(a)+'</details>' for q,a in [
 ('Preciso criar uma conta para cada familiar?','Não. Cadastre diferentes pessoas em Pessoas assistidas e escolha uma em cada solicitação.'),
 ('Posso solicitar cuidado para mim?','Sim. Selecione Eu na primeira etapa. O cadastro do titular utiliza o nome da conta.'),
 ('Posso salvar sem confirmar o e-mail?','Sim. A confirmação é exigida para enviar a solicitação.'),
 ('Posso editar depois de enviar?','A edição disponível é a do rascunho. Depois de enviar, a tela permite acompanhar os dados e o andamento.'),
 ('Por que o ícone da myzelo aparece quebrado ou como um quadrado azul?','Se isso acontecer ao acessar sua conta familiar, confira se o endereço salvo é myzelo.com.br. Abra o site no navegador e atualize a página. O navegador e o aplicativo de senhas podem guardar uma imagem antiga; depois que a equipe confirmar a publicação da correção, consulte novamente. Se o problema continuar, informe à equipe em qual aplicativo ele aparece, sua versão e se o ícone também falha na aba do navegador. Não há um prazo confirmado para o aplicativo atualizar a imagem.'),
 ('O pagamento cobra dinheiro de verdade?','Não nesta versão. A tela informa que é uma simulação e usa Autorizar pagamento de teste.'),
 ('O valor do exemplo é a tabela de preços?','Não. A revisão identifica o orçamento como valor temporário de teste.'),
 ('Tenho um relatório para baixar?','O histórico é consultado em Solicitações de cuidado → Visualizar. Não há exportação ou relatório documentado na versão atual.'),
 ('Concluído significa que houve repasse?','Não. O pagamento de teste continua autorizado e não há repasse real implementado.'),
 ('Onde fica o tutorial do profissional?','Esta entrega cobre somente o familiar. A entrada Profissional na central está identificada como Em breve.')
 ])),
 ('glossario','Glossário',table(['Termo','Significado'],[['Familiar','Conta de quem solicita e acompanha o cuidado, inclusive para si próprio.'],['Pessoa assistida','Pessoa que receberá o cuidado solicitado.'],['Contratante','Titular informado nos dados fiscais.'],['Rascunho','Solicitação salva que ainda não foi enviada.'],['Reserva','Aceite do profissional que abre um prazo para autorizar o pagamento.'],['Pagamento simulado','Autorização de teste, sem movimentação financeira real.'],['Histórico','Solicitações anteriores e seus detalhes e marcos de andamento.'],['Confirmação da conclusão','Ação da família após o profissional informar que terminou.']]))
], 'Você identifica a pendência e encontra a tarefa para continuar.', ['Leia primeiro o erro junto ao campo ou o aviso no topo da página.','Não repita uma ação de envio sem conferir o estado atual da solicitação.'])

page('exemplo-completo','Exemplo completo','Uma jornada: Marina e Helena','Acompanhe um exemplo fictício desde a criação da conta até o atendimento concluído.','Para repetir, utilize uma conta de treinamento e escolha datas válidas no ambiente em que está.','Cadastro familiar → Solicitações de cuidado → Concluído',[
 ('cenario','O cenário de treinamento',p('<strong>Marina Oliveira</strong> é a responsável pela conta e solicita cuidado para sua mãe, <strong>Helena Oliveira</strong>. O cuidado ocorre em uma residência fictícia em Campo Grande/MS, às quartas-feiras, por quatro horas, começando às 09:00. A necessidade escolhida é companhia e supervisão, sem procedimento de enfermagem.')+note('Nomes, endereço, contato e dados fiscais são fictícios. A data de 07/10/2026 pertence à captura; ao repetir o exercício, use uma data atual ou futura. O profissional e o valor também são de demonstração.')),
 ('preparacao','1. Preparar a conta e o pedido',steps('Marina escolhe Sou Familiar, cria sua conta e informa o WhatsApp no primeiro acesso.','Ela cadastra Helena em Pessoa assistida e salva o endereço da residência.','Marca Quarta, 4 horas, Data de início e Horário.','Escolhe Independente, Sem auxílio, Companhia e supervisão e Nenhum procedimento.','Retorna à lista, encontra o Rascunho e usa Continuar para conferir a revisão.','Confirma o e-mail recebido e envia a solicitação.')+shot('solicitacao-5-revisao','Revisão da solicitação de Helena antes do envio.')),
 ('reserva','2. Confirmar a reserva',steps('O pedido aparece como Buscando profissional. O Profissional Teste recebe a oportunidade e aceita.','Marina vê Aguardando pagamento e o prazo da reserva.','Ao abrir Simular pagamento, encontra uma pendência fiscal. Preenche os dados, salva e volta.','Confere o aviso de que não há cobrança real e usa Autorizar pagamento de teste.','O pedido passa para Atendimento autorizado.')+shot('pagamento-simulado','Autorização simulada da reserva no exemplo de treinamento.')),
 ('fechamento','3. Acompanhar e concluir',steps('Na data combinada, o profissional informa o início. Marina vê Em atendimento.','O profissional informa a conclusão; o pedido passa para Aguardando confirmação.','Marina confere o serviço e clica em Confirmar conclusão.','Na lista, o cartão aparece como Concluído. Ela usa Visualizar para consultar os detalhes quando precisar.')+shot('concluido','O exemplo chega ao estado Concluído com todos os marcos de andamento.')),
 ('praticar','Exercício para treinamento',p('Peça à pessoa em treinamento para localizar a pessoa assistida, o endereço, a agenda e o valor nos detalhes. Depois, pergunte em que momento o e-mail é exigido, onde preencher dados fiscais e qual a diferença entre autorizar o pagamento de teste e confirmar a conclusão.')+p('Respostas esperadas: e-mail no envio; dados fiscais em Meu perfil; pagamento autoriza o atendimento, enquanto confirmação registra o encerramento pela família.'))
], 'A jornada fica registrada como Concluído e pode ser revisitada pelo histórico.', ['A família não executa os botões do profissional. Os avanços dependem do aceite, início e término registrados por ele.','Neste exercício não houve atendimento real nem cobrança real.','Cada etapa do exemplo corresponde a uma tela real capturada no ambiente local.'])
